'use client';

// ─────────────────────────────────────────────────────────────────────────────
// Agent Lab — the builder page (browser).
//
// Left  = fields that CONFIGURE the agent + an ACCESS panel (what it can see) +
//         a NOTES pad for your own observations.
// Right = a test chat. Under every answer, a PROVENANCE panel shows where the
//         answer came from — which tools ran (with input/output) or "no tools,
//         the model's own knowledge" — plus what was sent to the model.
//
// Standalone: rendered without the global nav (see components/app-shell.tsx),
// calls POST /api/agent-lab, and does NOT use or affect the main CopilotKit chat.
// ─────────────────────────────────────────────────────────────────────────────

import Link from 'next/link';
import { useEffect, useState } from 'react';
import {
  AGENT_NAME,
  CATEGORY_HINT,
  CATEGORY_LABEL,
  DEFAULT_SYSTEM_PROMPT,
  MODEL_OPTIONS,
  TOOL_CATALOG,
  type AgentLabResponse,
  type AgentLabStep,
  type AgentLabUsage,
  type ToolCategory,
} from '@/features/agent-lab/catalog';

type TurnContext = { model: string; system: string; enabledTools: string[]; messageCount: number };

type ChatMessage = {
  role: 'user' | 'assistant';
  content: string;
  steps?: AgentLabStep[];
  usage?: AgentLabUsage;
  context?: TurnContext;
};

const CATEGORY_ORDER: ToolCategory[] = ['template', 'real', 'workflow-action'];

export default function AgentLabPage() {
  const [model, setModel] = useState(MODEL_OPTIONS[0].id);
  const [customModel, setCustomModel] = useState('');
  const [system, setSystem] = useState(DEFAULT_SYSTEM_PROMPT);
  const [temperature, setTemperature] = useState(0.7);
  const [maxSteps, setMaxSteps] = useState(6);
  const [enabled, setEnabled] = useState<Record<string, boolean>>(
    Object.fromEntries(TOOL_CATALOG.map((t) => [t.id, true]))
  );
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [inputText, setInputText] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [notes, setNotes] = useState('');

  // Load/save your notes locally so they survive a refresh.
  useEffect(() => {
    const saved = localStorage.getItem('agent-lab-notes');
    if (saved) {
      setNotes(saved);
    }
  }, []);
  useEffect(() => {
    localStorage.setItem('agent-lab-notes', notes);
  }, [notes]);

  const activeModel = customModel.trim() || model;
  const enabledTools = Object.keys(enabled).filter((k) => enabled[k]);

  async function send() {
    const text = inputText.trim();
    if (!text || loading) {
      return;
    }
    setError('');
    const next: ChatMessage[] = [...messages, { role: 'user', content: text }];
    setMessages(next);
    setInputText('');
    setLoading(true);

    // Capture EXACTLY what this turn sends to the model, for the provenance panel.
    const turnContext: TurnContext = {
      model: activeModel,
      system,
      enabledTools,
      messageCount: next.length,
    };

    try {
      const res = await fetch('/api/agent-lab', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: activeModel,
          system,
          temperature,
          maxSteps,
          enabledTools,
          messages: next.map((m) => ({ role: m.role, content: m.content })),
        }),
      });
      const data = (await res.json()) as AgentLabResponse;
      if (data.error) {
        setError(data.error);
        setMessages([...next, { role: 'assistant', content: `⚠️ ${data.error}` }]);
      } else {
        setMessages([
          ...next,
          { role: 'assistant', content: data.text, steps: data.steps, usage: data.usage, context: turnContext },
        ]);
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="mx-auto max-w-[1280px] px-4 pb-16 text-neutral-900 dark:text-neutral-100">
      {/* ── Sticky header with BACK button ─────────────────────────── */}
      <header className="sticky top-0 z-10 -mx-4 mb-4 flex items-center gap-3 border-b border-neutral-200 bg-white/90 px-4 py-3 backdrop-blur dark:border-neutral-800 dark:bg-neutral-950/90">
        <Link
          href="/"
          className="rounded-lg border border-neutral-300 px-3 py-1.5 text-sm hover:bg-neutral-100 dark:border-neutral-700 dark:hover:bg-neutral-800"
        >
          ← Back to main
        </Link>
        <div>
          <h1 className="text-base font-semibold">🤖 {AGENT_NAME} — Agent Lab</h1>
          <p className="text-[11px] text-neutral-500 dark:text-neutral-400">
            Configure the agent, chat, and see exactly where each answer comes from. Separate from your main chat.
          </p>
        </div>
      </header>

      <div className="grid grid-cols-1 gap-4 lg:grid-cols-[400px_1fr]">
        {/* ── LEFT: BUILDER + ACCESS + NOTES ───────────────────────── */}
        <div className="flex flex-col gap-3">
          <Section title="Model">
            <select className={fieldClass} value={model} onChange={(e) => setModel(e.target.value)}>
              {MODEL_OPTIONS.map((m) => (
                <option key={m.id} value={m.id}>
                  {m.label}
                </option>
              ))}
            </select>
            <input
              className={`${fieldClass} mt-2`}
              placeholder="…or type any model id (overrides dropdown)"
              value={customModel}
              onChange={(e) => setCustomModel(e.target.value)}
            />
            <p className="mt-1.5 text-[11px] text-neutral-500 dark:text-neutral-400">
              Using <b>{activeModel}</b>.{' '}
              {activeModel.includes('/') ? 'Gateway model → needs AI_GATEWAY_API_KEY.' : 'Direct OpenAI → needs OPENAI_API_KEY.'}
            </p>
          </Section>

          <Section title="System prompt — what the agent does / thinks">
            <textarea
              className={`${fieldClass} min-h-[110px] resize-y`}
              value={system}
              onChange={(e) => setSystem(e.target.value)}
            />
          </Section>

          <Section title="Tools the agent may use">
            {CATEGORY_ORDER.map((cat) => (
              <div key={cat} className="mb-3 last:mb-0">
                <div className="text-[11px] font-semibold uppercase tracking-wide text-neutral-600 dark:text-neutral-300">
                  {CATEGORY_LABEL[cat]}
                </div>
                <div className="mb-1.5 text-[11px] text-neutral-500 dark:text-neutral-400">{CATEGORY_HINT[cat]}</div>
                {TOOL_CATALOG.filter((t) => t.category === cat).map((t) => (
                  <label key={t.id} className="mb-1 flex cursor-pointer items-start gap-2 text-[13px]" title={t.desc}>
                    <input
                      type="checkbox"
                      className="mt-0.5"
                      checked={!!enabled[t.id]}
                      onChange={(e) => setEnabled({ ...enabled, [t.id]: e.target.checked })}
                    />
                    <span>
                      {t.label}
                      {!t.real && <span className="text-amber-600 dark:text-amber-400"> (demo)</span>}
                    </span>
                  </label>
                ))}
              </div>
            ))}
          </Section>

          <Section title="Advanced (technical)">
            <div className="flex gap-3">
              <label className="flex-1 text-[11px] text-neutral-500 dark:text-neutral-400">
                Temperature
                <input
                  className={`${fieldClass} mt-1`}
                  type="number"
                  step={0.1}
                  min={0}
                  max={2}
                  value={temperature}
                  onChange={(e) => setTemperature(Number(e.target.value))}
                />
              </label>
              <label className="flex-1 text-[11px] text-neutral-500 dark:text-neutral-400">
                Max steps (loop cap)
                <input
                  className={`${fieldClass} mt-1`}
                  type="number"
                  min={1}
                  max={20}
                  value={maxSteps}
                  onChange={(e) => setMaxSteps(Number(e.target.value))}
                />
              </label>
            </div>
          </Section>

          {/* ── ACCESS PANEL — answers "what can the agent see?" ──────── */}
          <Section title="What this agent can access right now">
            <ul className="space-y-1 text-[12px]">
              <li>✅ Its system prompt (the box above)</li>
              <li>✅ This conversation ({messages.length} message{messages.length === 1 ? '' : 's'})</li>
              <li>
                ✅ {enabledTools.length} enabled tool{enabledTools.length === 1 ? '' : 's'}
                {enabledTools.length > 0 && (
                  <span className="text-neutral-500 dark:text-neutral-400">: {enabledTools.join(', ')}</span>
                )}
              </li>
              <li className="text-neutral-500 dark:text-neutral-400">
                ❌ No long-term memory, documents, or files — <b>unless a tool provides them</b>.
              </li>
            </ul>
            <p className="mt-2 text-[11px] text-neutral-500 dark:text-neutral-400">
              Tools that bring in outside data: <b>recallNotes</b> (session memory), <b>fetchWebPage</b> (the web),{' '}
              <b>getFxRate</b> (live Bank of Canada data). Turn one off and the agent instantly loses that access.
            </p>
          </Section>

          {/* ── YOUR NOTES ───────────────────────────────────────────── */}
          <Section title="Your notes (saved on this device)">
            <textarea
              className={`${fieldClass} min-h-[90px] resize-y`}
              placeholder="Jot what you notice about the agent as you test…"
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
            />
          </Section>

          <button
            type="button"
            onClick={() => setMessages([])}
            className="rounded-lg border border-neutral-300 px-3 py-2 text-[13px] text-neutral-500 hover:bg-neutral-100 dark:border-neutral-700 dark:hover:bg-neutral-800"
          >
            Clear conversation
          </button>
        </div>

        {/* ── RIGHT: CHAT + PROVENANCE ─────────────────────────────── */}
        <div className="flex flex-col gap-3">
          <div className="max-h-[65vh] min-h-[300px] space-y-3 overflow-y-auto rounded-xl border border-neutral-200 bg-neutral-50 p-4 dark:border-neutral-800 dark:bg-neutral-900">
            {messages.length === 0 && (
              <p className="text-sm text-neutral-500 dark:text-neutral-400">
                Ask {AGENT_NAME} anything. Try{' '}
                <i>“What time is it, what is 18% of 240, and what was the USD→CAD rate in 2024?”</i> to watch it chain
                three tools — then read the “Where this came from” panel under the answer.
              </p>
            )}

            {messages.map((m, i) => (
              <div key={i} className={m.role === 'user' ? 'flex justify-end' : 'flex flex-col items-start'}>
                <div
                  className={
                    m.role === 'user'
                      ? 'max-w-[85%] rounded-lg bg-blue-600 px-3 py-2 text-sm whitespace-pre-wrap text-white'
                      : 'max-w-[92%] rounded-lg border border-neutral-200 bg-white px-3 py-2 text-sm whitespace-pre-wrap dark:border-neutral-700 dark:bg-neutral-800'
                  }
                >
                  {m.content}
                </div>

                {m.role === 'assistant' && m.context && <Provenance msg={m} />}
              </div>
            ))}

            {loading && <p className="text-sm text-neutral-500 dark:text-neutral-400">{AGENT_NAME} is thinking…</p>}
          </div>

          {error && <p className="text-[13px] text-red-500">{error}</p>}

          <div className="flex gap-2">
            <input
              className={`${fieldClass} flex-1`}
              placeholder={`Message ${AGENT_NAME}…`}
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') {
                  send();
                }
              }}
            />
            <button
              type="button"
              onClick={send}
              disabled={loading}
              className="rounded-lg bg-blue-600 px-5 text-sm text-white disabled:opacity-60"
            >
              Send
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

// ── Provenance panel: "where did this answer come from?" ─────────────────────
function Provenance({ msg }: { msg: ChatMessage }) {
  const ctx = msg.context;
  if (!ctx) {
    return null;
  }
  const toolCalls = (msg.steps ?? []).flatMap((s) =>
    s.toolCalls.map((tc, j) => ({ tool: tc.tool, input: tc.input, output: s.toolResults[j]?.output }))
  );
  const usedTools = toolCalls.length > 0;

  return (
    <div className="mt-1.5 w-full max-w-[92%] rounded-lg border border-neutral-200 bg-white p-2 text-[11px] dark:border-neutral-800 dark:bg-neutral-950">
      <div className="mb-1 font-semibold text-neutral-600 dark:text-neutral-300">Where this came from</div>

      {usedTools ? (
        <div className="mb-1 text-emerald-700 dark:text-emerald-400">
          Grounded in {toolCalls.length} tool call{toolCalls.length === 1 ? '' : 's'}:{' '}
          {toolCalls.map((t) => t.tool).join(', ')}
        </div>
      ) : (
        <div className="mb-1 text-amber-700 dark:text-amber-400">
          No tools used — this answer is the model’s own knowledge (not memory, documents, or files).
        </div>
      )}

      {toolCalls.map((t, j) => (
        <div key={j} className="mb-1 rounded border border-neutral-200 p-1.5 dark:border-neutral-800">
          <span className="font-mono text-blue-600 dark:text-blue-400">🔧 {t.tool}</span>
          <pre className="mt-0.5 overflow-x-auto whitespace-pre-wrap text-neutral-500 dark:text-neutral-400">
            in: {JSON.stringify(t.input)}
          </pre>
          <pre className="overflow-x-auto whitespace-pre-wrap text-neutral-500 dark:text-neutral-400">
            out: {JSON.stringify(t.output)}
          </pre>
        </div>
      ))}

      <details className="mt-1">
        <summary className="cursor-pointer text-neutral-500 dark:text-neutral-400">
          What the model received this turn
          {msg.usage?.totalTokens ? ` · ${msg.usage.totalTokens} tokens` : ''}
        </summary>
        <div className="mt-1 space-y-1 text-neutral-500 dark:text-neutral-400">
          <div>
            <b>Model:</b> {ctx.model}
          </div>
          <div>
            <b>Tools available:</b> {ctx.enabledTools.length ? ctx.enabledTools.join(', ') : 'none'}
          </div>
          <div>
            <b>Conversation:</b> {ctx.messageCount} message{ctx.messageCount === 1 ? '' : 's'}
          </div>
          <div>
            <b>System prompt:</b>
            <pre className="mt-0.5 overflow-x-auto whitespace-pre-wrap">{ctx.system}</pre>
          </div>
        </div>
      </details>
    </div>
  );
}

const fieldClass =
  'w-full rounded-lg border border-neutral-300 bg-white px-2.5 py-2 text-sm text-neutral-900 outline-none focus:border-blue-500 dark:border-neutral-700 dark:bg-neutral-900 dark:text-neutral-100';

function Section({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <div className="rounded-xl border border-neutral-200 bg-white p-3 dark:border-neutral-800 dark:bg-neutral-900">
      <div className="mb-2 text-[11px] font-semibold uppercase tracking-wide text-neutral-500 dark:text-neutral-400">
        {title}
      </div>
      {children}
    </div>
  );
}
